import { Component, Prop, h, Host, Event, EventEmitter, Element } from '@stencil/core';
import { dir } from '@src/shared/i18n';
import { KsIconChevronLeft, KsIconChevronRight } from '@fe-infra/keystone-icons-stencil';

const prefix = 'arrow-pagination';

@Component({
  tag: 'ks-arrow-pagination',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsArrowPagination {
  @Element() el!: HTMLKsArrowPaginationElement;

  /** */
  @Prop() currentIndex = -1;

  /** */
  @Prop() count = 0;

  /** */
  @Prop() slidesToShow = 1;

  /** */
  @Prop() infinite = false;

  /** */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<'left' | 'right'>;

  /** */
  @Event({ bubbles: false, composed: false }) ksArrowOver!: EventEmitter;

  /** */
  @Event({ bubbles: false, composed: false }) ksArrowLeave!: EventEmitter;

  /** */
  @Event({ bubbles: false, composed: false }) ksArrowEnter!: EventEmitter;

  private renderArrowButton = (orient: 'left' | 'right', disabled = false) => (
    <ks-icon-button
      class={{
        [`${prefix}--arrow`]: !disabled,
      }}
      size="sm"
      variant="text"
      disabled={disabled}
      onClick={() => {
        this.ksChange.emit(orient);
      }}
      onMouseOver={() => this.ksArrowOver.emit()}
      onMouseLeave={() => this.ksArrowLeave.emit()}
      onMouseEnter={() => this.ksArrowEnter.emit()}
    >
      {orient === 'left' ? <KsIconChevronLeft /> : <KsIconChevronRight />}
    </ks-icon-button>
  );

  render() {
    return (
      <Host KsArrowPagination>
        {this.renderArrowButton(dir() === 'ltr' ? 'left' : 'right', !this.infinite && this.currentIndex === 1)}

        <span class={`${prefix}--text`}>{`${this.currentIndex} / ${this.count}`}</span>
        {this.renderArrowButton(dir() === 'ltr' ? 'right' : 'left', !this.infinite && this.currentIndex >= this.count)}
      </Host>
    );
  }
}
